"""Summarize results/*.json into results/summary.md.

Usage: python3 -I summarize.py
"""
import glob
import json
import os
from collections import Counter

here = os.path.dirname(os.path.abspath(__file__))
rows = []
lines = ["# LEAD-041: FOMC application, summary", "",
         "Generated by summarize.py from results/results_*.json.", "",
         "| spec | decision | windows | quarters | contested | departure profile (1st, 2nd, 3rd) | verdicts (windows with >= 4 contests) | windows with a verdict | alternation p(more), p(fewer) |",
         "|---|---|---|---|---|---|---|---|---|"]
for f in sorted(glob.glob(os.path.join(here, "results", "results_*.json"))):
    d = json.load(open(f))
    pw = [r for r in d["per_window"] if r["contested"] >= 4]
    c = Counter(r["verdict"] for r in pw)
    shown = [f"{r['window']}: {r['verdict']} ({r['leading']}{', ' + r['sign'] if r['sign'] else ''})"
             for r in d["per_window"] if r["verdict"] in ("ambivalent", "prevails", "split by context")]
    prof = ", ".join(f"{x:.2f}" for x in d["departure_profile"])
    lines.append(f"| {d['spec']} | {d['decision']} | {d['windows']} | {d['n_quarters']} | {d['n_contested']} | {prof} | "
                 f"{dict(c)} | {'; '.join(shown) or 'none'} | {d['alternation']['p_more']:.3f}, {d['alternation']['p_fewer']:.3f} |")
lines += ["", "## Spec A, nominal, two-year windows", "",
          "| window | contested | reversal | p ambivalence | alignment (inflation, employment, inertia) | p lead | verdict | leading |",
          "|---|---|---|---|---|---|---|---|"]
d = json.load(open(os.path.join(here, "results", "results_A_nominal_window.json")))
for r in d["per_window"]:
    if r["contested"] == 0:
        continue
    a = r["alignment"]
    al = ", ".join(f"{a[k]:.2f}" for k in ("inflation", "employment", "inertia")) if a else ""
    lines.append(f"| {r['window']} | {r['contested']} | {r['reversal']} | {r['p_ambivalence']} | {al} | {r['p_lead']} | {r['verdict']} | {r['leading']} |")
p = os.path.join(here, "results", "power.txt")
if os.path.exists(p):
    lines += ["", "## Power (power.py)", "", "```", open(p).read().rstrip(), "```"]
open(os.path.join(here, "results", "summary.md"), "w").write("\n".join(lines) + "\n")
print("\n".join(lines))
